window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"UiXOnmM3gsg","speaker":"Kamina Johnson Smith","role":"Foreign Minister","country":"Jamaica","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=UiXOnmM3gsg","date":"20260926","title":"🇯🇲 Jamaica - Foreign Minister Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1009,"words":2091,"counts":{"claims":27,"promises":1,"attacks":0},"topics":[{"topic":"UN reform","share":0.2132,"seconds":215},{"topic":"Climate finance","share":0.1229,"seconds":124},{"topic":"AI governance","share":0.0751,"seconds":76},{"topic":"Jamaica reconstruction","share":0.0748,"seconds":76},{"topic":"Reparations","share":0.0745,"seconds":75},{"topic":"Disaster recovery","share":0.0676,"seconds":68},{"topic":"Jamaica security","share":0.0668,"seconds":67},{"topic":"Jamaica climate","share":0.0626,"seconds":63},{"topic":"Haiti","share":0.062,"seconds":63},{"topic":"Multilateral cooperation","share":0.0613,"seconds":62},{"topic":"Jamaica economy","share":0.0598,"seconds":60},{"topic":"Jamaica crime","share":0.0595,"seconds":60}],"timeline":[[7,72,null],[74,136,"Multilateral cooperation"],[136,204,"UN reform"],[205,273,"Disaster recovery"],[275,338,"Jamaica climate"],[339,415,"Jamaica reconstruction"],[417,480,"Climate finance"],[482,542,"Jamaica economy"],[544,604,"Climate finance"],[605,681,"AI governance"],[682,742,"Jamaica crime"],[743,810,"Jamaica security"],[812,874,"Haiti"],[875,950,"Reparations"],[952,1017,"UN reform"],[1018,1082,"UN reform"],[1084,1102,"UN reform"]],"stances":{"Multilateral cooperation":"Kamina Johnson Smith argues that the flaws of multilateralism should not lead to abandoning it, as a rules-based international order is essential for the sovereignty and security of small states.","UN reform":"Kamina Johnson Smith advocates for comprehensive United Nations reform to make the organization more representative, accountable, and efficient, highlighting Jamaica's leadership role in this effort.","Disaster recovery":"Kamina Johnson Smith states that Hurricane Melissa caused catastrophic damage and loss estimated at a portion of Jamaica's GDP.","Jamaica climate":"Kamina Johnson Smith argues that despite Jamaica's prudent economic planning and disaster financing, small island developing states remain fundamentally inequitable in their exposure to catastrophic climate events.","Jamaica reconstruction":"Kamina Johnson Smith states that Jamaica is committed to rebuilding better and differently by establishing a new authority to drive reconstruction and embed resilience.","Climate finance":"Kamina Johnson Smith argues that climate finance must be more accessible and affordable, and that international financial architecture should recognize the vulnerability of Small Island Developing States beyond per capita income.","Jamaica economy":"Kamina Johnson Smith attributes Jamaica's economic stability and disaster response capacity to disciplined long-term planning and policy choices made prior to the crisis.","AI governance":"Kamina Johnson Smith argues that AI must not deepen inequalities and requires investment in infrastructure, skills, and capacity for developing countries alongside global governance frameworks.","Jamaica crime":"Kamina Johnson Smith calls for cross-border cooperation on firearms and notes Jamaica's domestic security investments have led to a record low in homicides.","Jamaica security":"Kamina Johnson Smith states that Jamaica has achieved the status of the most peaceful country in the Caribbean and calls for international support to address gang violence in Haiti.","Haiti":"Kamina Johnson Smith asserts that armed gangs must not determine Haiti's future and that security is a prerequisite for humanitarian relief, political stability, and credible elections.","Reparations":"Kamina Johnson Smith asserts that reparatory justice is fundamentally about truth, acknowledgement, and compensation, and confirms Jamaica's active support for a General Assembly resolution on the matter."},"claims":[{"t":74,"quote":"Wars and conflicts are devastating communities and displacing millions.","topic":"Multilateral cooperation","kind":"fact"},{"t":82,"quote":"Climate change is destroying lives, livelihoods, and decades of development in a matter of hours.","topic":"Multilateral cooperation","kind":"fact"},{"t":155,"quote":"Our permanent representative was privileged to co-chair with New Zealand the UNAT initiatives informal ad hoc working group on mandate implementation review.","topic":"UN reform","kind":"fact"},{"t":166,"quote":"That work culminated in General Assembly Resolution 80251, an important framework for improving how UN mandates are created, implemented, and reviewed.","topic":"UN reform","kind":"fact"},{"t":258,"quote":"On the 28th of October last year, Hurricane Melissa struck our island.","topic":"Disaster recovery","kind":"fact"},{"t":262,"quote":"In a matter of hours, the most catastrophic hurricane in our modern history inflicted damage and loss estimated at of our GDP.","topic":"Disaster recovery","kind":"number"},{"t":277,"quote":"In a matter of hours, more than half the value of an entire year of national economic output was damaged or lost.","topic":"Jamaica climate","kind":"number"},{"t":292,"quote":"Years of fiscal discipline had allowed us to build buffers. We had put in place disaster risk financing including catastrophe insurance and an independently sponsored catastrophe bond.","topic":"Jamaica climate","kind":"fact"},{"t":326,"quote":"Jamaica's reforms balanced economic orthodoxy with innovation and expanded support for the most vulnerable.","topic":"Jamaica climate","kind":"self_credit"},{"t":373,"quote":"That is why the government of Prime Minister Andrew Holes established the National Reconstruction and Resilience Authority, NAR.","topic":"Jamaica reconstruction","kind":"fact"},{"t":404,"quote":"We have also submitted our updated nationally determined contribution, completed our long-term strategy for a lowcarbon climate resilient future and advanced our national adaptation plan.","topic":"Jamaica reconstruction","kind":"fact"},{"t":438,"quote":"Income alone does not and cannot measure A country does not become less vulnerable to hurricanes and other natural disasters because its per capita income has crossed an arbitrary threshold.","topic":"Climate finance","kind":"fact"},{"t":475,"quote":"Over the past decade, we have undertaken difficult reforms and made difficult decisions.","topic":"Climate finance","kind":"self_credit"},{"t":482,"quote":"Our debt, which once stood at more than 140% of GDP, was brought down to 62% before Melissa with unemployment then at a historic low of 3.4%.","topic":"Jamaica economy","kind":"number"},{"t":514,"quote":"unemployment still stands at a relative low of 3.7%.","topic":"Jamaica economy","kind":"number"},{"t":555,"quote":"Developing countries cannot reasonably be expected to simultaneously finance climate adaptation, modernize infrastructure, strengthen social protection, manage debt, absorb external shocks, and achieve the sustainable development goals without an international financial system responsive to their realities.","topic":"Climate finance","kind":"fact"},{"t":665,"quote":"Last year from this very podium, Prime Minister Andrew Holes called for a global war on gangs","topic":"AI governance","kind":"fact"},{"t":738,"quote":"In 2025, Jamaica recorded its lowest number of homicides in more than three decades.","topic":"Jamaica crime","kind":"number"},{"t":743,"quote":"And in 2026, with even further reductions, the Global Peace Index ranked Jamaica the most peaceful country in the Caribbean.","topic":"Jamaica security","kind":"fact"},{"t":824,"quote":"Armed gangs cannot be allowed to determine Haiti's future, nor that of the region.","topic":"Haiti","kind":"fact"},{"t":852,"quote":"The suffering of the Cuban people is of deep concern to Jamaica.","topic":"Haiti","kind":"fact"},{"t":937,"quote":"Jamaica not only supported the General Assembly resolution put forward by Ghana on March 25th of this year, but we also delivered to Buckingham Palace a petition framing critical questions on the matter of reparations.","topic":"Reparations","kind":"fact"},{"t":952,"quote":"The petition has now been referred to the judicial committee of the privy council.","topic":"UN reform","kind":"fact"},{"t":957,"quote":"Mr. President 64 years after Jamaica proudly raised our black, green, and gold flag as politically independent nation.","topic":"UN reform","kind":"fact"},{"t":1018,"quote":"When countries that have acted responsibility are not penalized for shocks they did not create.","topic":"UN reform","kind":"fact"},{"t":1043,"quote":"Our own journey has taught us that vulnerability need not mean helplessness, that discipline creates resilience, that partnership multiplies possibility, and that even in moments of profound crisis, nations can choose to build forward.","topic":"UN reform","kind":"self_credit"},{"t":1084,"quote":"That is the United Nations Jamaica believes in.","topic":"UN reform","kind":"fact"}],"promises":[{"t":1087,"quote":"And that is the United Nations we will continue to work towards reforming and renewing.","topic":"UN reform","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":7,"topic":null,"text":"I now give the floor to her excellency Camina Johnson Smith, Minister of Foreign Affairs and Foreign Trades of Mr. President, on behalf of the government and people of Jamaica, I congratulate you on your election as president of this 81st session of the General Assembly and assure you of Jamaica's full support. I also commend your predecessor, her excellency Analena Burbach, for her stewardship of the assembly during the historic 80th session. and to Secretary General Antonio Gutes, I convey Jamaica's profound appreciation for your steadfast leadership through a decade of extraordinary global uncertainty. Mr. President, your theme for this session could hardly be more timely because today trust is in short supply."},{"t":74,"topic":"Multilateral cooperation","text":"Wars and conflicts are devastating communities and displacing millions. Geopolitical tensions are deepening. Climate change is destroying lives, livelihoods, and decades of development in a matter of hours. New technologies, including artificial intelligence, are offer extraordinary promise while presenting risks we have not yet fully And at the very moment when collective action is most needed, confidence in multilateralism itself is being tested. Jamaica's position is clear. The shortcomings of multilateralism cannot be solved by abandoning multilateralism. For small states like ours, a rules-based international order is not an abstract diplomatic preference. It is fundamental to our sovereignty or security and our development. But neither can we safeguard multilateralism simply by defending it."},{"t":136,"topic":"UN reform","text":"We must reform it. We must make it more representative, more accountable, more efficient, and more responsive to the needs and realities of the people it was created to serve. That is why Jamaica has chosen not merely to call for reform, but to help lead it. Our permanent representative was privileged to co-chair with New Zealand the UNAT initiatives informal ad hoc working group on mandate implementation review. That work culminated in General Assembly Resolution 80251, an important framework for improving how UN mandates are created, implemented, and reviewed. Jamaica now continues that work alongside Norway. Our objective is straightforward. A United Nations that spends less time sustaining process for its own sake and more time fulfilling its purpose. That is the multilateralism Jamaica believes in. Mr. President, the selection of the next Secretary General will be one of the most consequential decisions before member states this year."},{"t":205,"topic":"Disaster recovery","text":"Jamaica proudly joins our CARACOM family in supporting the candidacy of her excellency Caroline Rodriguez Burkett of the Cooperative Republic of candidacy also speaks to something larger. Small states have long served the international system as bridgebuilders, consensus makers, and problem solvers. We learned very early that influence does not depend only on size or power. It can come from credibility, from dialogue, from principle, and the capacity to bring people together. These are the strengths which our multilateral system needs now more than ever. Mr. President, for Jamaica, the consequences of global challenges are not theoretical. On the 28th of October last year, Hurricane Melissa struck our island. In a matter of hours, the most catastrophic hurricane in our modern history inflicted damage and loss estimated at of our GDP."},{"t":275,"topic":"Jamaica climate","text":"Think about that. In a matter of hours, more than half the value of an entire year of national economic output was damaged or lost. A single event Jamaica had prepared. Years of fiscal discipline had allowed us to build buffers. We had put in place disaster risk financing including catastrophe insurance and an independently sponsored catastrophe bond. Those measures gave us immediate liquidity. But no level of prudent national planning can fully insulate a small developing state from a climate event of that magnitude. And therein lies the fundamental inequity faced by small island developing states. We can do everything right. In fact, Jamaica's reforms balanced economic orthodoxy with innovation and expanded support for the most vulnerable. And yet, one hurricane could erase decades of progress."},{"t":339,"topic":"Jamaica reconstruction","text":"We are deeply grateful to our international partners, our Caraccom family, our Jamaican diaspora, and the thousands of individuals and organizations which stood with us during our hour of need. Jamaica has not simply resolved to recover. We have resolved to rebuild better and differently. Our resilience must not be measured by how much suffering we can withstand. It must be measured by how well we prepare, how quickly we recover, how intelligently we adapt, and whether we emerge stronger. That is why the government of Prime Minister Andrew Holes established the National Reconstruction and Resilience Authority, NAR. Its mandate is to drive reconstruction at speed and scale, to coordinate major infrastructure projects, crowding investment, and critically to embed resilience in the Jamaica we are rebuilding. We're not simply replacing what Melissa has destroyed. We are building the Jamaica that must withstand the storms of We have also submitted our updated nationally determined contribution, completed our long-term strategy for a lowcarbon climate resilient future and advanced our national adaptation plan."},{"t":417,"topic":"Climate finance","text":"But national ambition must be matched by international action. We must revive Climate finance must become more accessible, affordable, and predictable. And the international financial architecture must finally recognize what SIDs have so long argued. Income alone does not and cannot measure A country does not become less vulnerable to hurricanes and other natural disasters because its per capita income has crossed an arbitrary threshold. We therefore continue to advocate for the use of measures that go beyond GDP, including multi-dimensional vulnerability indices in determining access to concessional and development Mr. President, Jamaica brings this message to the international community from a position not only of vulnerability, but one of Over the past decade, we have undertaken difficult reforms and made difficult decisions."},{"t":482,"topic":"Jamaica economy","text":"Our debt, which once stood at more than 140% of GDP, was brought down to 62% before Melissa with unemployment then at a historic low of 3.4%. We built macroeconomic stability, strengthened investor confidence, and created the fiscal space that ultimately helped us respond to the greatest natural disaster in our modern history. We are proud and heartened that notwithstanding Melissa, Jamaica's credit ratings have either been stabilized or upgraded, and unemployment still stands at a relative low of 3.7%. Those gains did not happen by accident. They required discipline, partnership, sacrifice, consistency, and long-term planning. Our experience has taught us that the strongest response to a crisis begins long before the crisis arrives in the choices we make, the institutions we build, and the buffers we create."},{"t":544,"topic":"Climate finance","text":"Jamaica will continue to take responsibility for the things within our control. But domestic responsibility must be matched by international solidarity and cooperation. Developing countries cannot reasonably be expected to simultaneously finance climate adaptation, modernize infrastructure, strengthen social protection, manage debt, absorb external shocks, and achieve the sustainable development goals without an international financial system responsive to their realities. We do not ask to be relieved of responsibility. We ask for an international system that gives responsible countries the space and support to succeed. Mr. President, that opportunity increasingly depends on technology. Jamaica sees digital transformation and responsible artificial intelligence as powerful tools. They can enhance productivity, innovation, and sustainable development for our people."},{"t":605,"topic":"AI governance","text":"Indeed, they can be an equalizing force for the world. We must therefore not allow AI to deepen old inequalities and create an entirely new global divide. Developing countries require investment in infrastructure, skills, and capacity. And all countries require governance frameworks that safeguard privacy and intellectual property, ensure data integrity, and promote the ethical and responsible use of emerging technologies without stifling innovation. The pact for the future, the global digital compact and the Abbas provide important foundations. Our task now as a global community is to translate commitments into action. Mr. President, development also requires peace and security for Jamaica and our wider Caribbean region. Transnational organized crime remains a serious threat. Last year from this very podium, Prime Minister Andrew Holes called for a global war on gangs, a coordinated international effort capable of matching the reach, financing, and sophistication of transnational criminal networks."},{"t":682,"topic":"Jamaica crime","text":"Jamaica reiterates that call today. Illicit firearms do not manufacture themselves in our communities. They cross borders. Criminal money crosses borders. Criminal networks exploit technology and operate across borders. Our response must therefore also cross borders. We call for stronger cooperation in firearms tracing and interdiction, intelligence and information sharing, financial investigations and law enforcement capacity building. We also urge major arms enforcing exporting states to strengthen export controls and post delivery verification. At home, Jamaica has invested heavily in our security forces, strengthened legislation, enhanced intelligence gathering, oversight, and transformed policing. The results are remarkable by any standard. In 2025, Jamaica recorded its lowest number of homicides in more than three decades."},{"t":743,"topic":"Jamaica security","text":"And in 2026, with even further reductions, the Global Peace Index ranked Jamaica the most peaceful country in the Caribbean. We recognize that there remains work to be done, but the direction is clear. And our objective is not merely fewer crimes. It is a durable ecosystem of peace in which every Jamaican can feel safe, raise a family, do business, and fulfill his or her potential and retire in paradise. Mr. President, nowhere in our region is the challenge of criminal gangs more devastating than in our caraccom sister nation of Haiti. Jamaica stands firmly with the Haitian people. We urge sustained international support for the gang suppression force, the Haitian National Police and its armed forces. This support must include the financial, logistical and operational resources necessary to restore security. We further call for the security council to renew the mandate of the GSF at this imperfect but particularly critical juncture."},{"t":812,"topic":"Haiti","text":"We are at a crossroads. We can either lose gains or we can build on progress made. The international community must send an unequivocal message. Armed gangs cannot be allowed to determine Haiti's future, nor that of the region. Security must create the space for sustained humanitarian relief, developmental and economic progress. But even more foundationally, security must create the space for political stability, democratic governance, and credible elections led and owned by the Haitian people. Mr. President, the suffering of the Cuban people is of deep concern to Jamaica. We encourage domestic reform and greater integration of Cuba into the international economic system, supported by policies that create pathways for progress and eliminating the dire humanitarian crisis rather than perpetuating isolation under the blockade."},{"t":875,"topic":"Reparations","text":"We call for continued dialogue and constructive engagement. Mr. President Jamaica also remains deeply concerned by the terrible human cost of armed conflicts across the world. Wherever conflict occurs, our principles must remain consistent. International humanitarian law must be respected. Civilians must be protected. International law and the charter of the United Nations must be upheld. And diplomacy must remain our first and most persistent instrument for resolving disputes. Respect for international law, including due regard for the decisions of the international court of justice, is indispensable to the peaceful international order on which small states depend. Mr. President, Jamaica believes that reparatory justice is at its heart about truth, acknowledgement, justice, repair, compensation, development, and Jamaica not only supported the General Assembly resolution put forward by Ghana on March 25th of this year, but we also delivered to Buckingham Palace a petition framing critical questions on the matter of reparations."},{"t":952,"topic":"UN reform","text":"The petition has now been referred to the judicial committee of the privy council. Mr. President 64 years after Jamaica proudly raised our black, green, and gold flag as politically independent nation. We remain cleareyed about the world around us. We know its dangers, but we also believe deeply in its possibilities. The United Nations must change if it is to remain credible. Jamaica supports the revitalization of this general assembly, meaningful reform of the Security Council, and greater coherence, efficiency, and accountability across the United Nations system. Reform is not an act of disloyalty to this institution. Reform is how we preserve it. Ultimately, however, Mr. President, multilateral multilateralism must mean something beyond these walls. For a small state like Jamaica, its value is felt when our people are safer. When opportunity is expanded, when vulnerability does not become a barrier to development."},{"t":1018,"topic":"UN reform","text":"When countries that have acted responsibility are not penalized for shocks they did not create. And when the voice of a small nation carries the same dignity as that of a large one. That is why Jamaica remains committed to this institution. Not because it is perfect, but because we're grateful for what it has achieved and we believe in what it can become. Small states can help lead that effort. Our own journey has taught us that vulnerability need not mean helplessness, that discipline creates resilience, that partnership multiplies possibility, and that even in moments of profound crisis, nations can choose to build forward. So, let us restore trust through what we do. Let us manage transformation with purpose. Let us bring the same seriousness to preventing crises that we do to responding to them. And let us never lose sight of the simple idea on which this institution was founded. That nations working together can achieve what none of us can achieve alone."},{"t":1084,"topic":"UN reform","text":"That is the United Nations Jamaica believes in. And that is the United Nations we will continue to work towards reforming and renewing. I thank you. I thank the Minister of Foreign Affairs and Foreign Trade of Jamaica."}],"compare":[{"topic":"UN & its reform","share":0.2132,"mean":0.2047,"rank":84,"others":170},{"topic":"Climate Change","share":0.1229,"mean":0.0424,"rank":24,"others":77},{"topic":"Artificial Intelligence","share":0.0751,"mean":0.0503,"rank":52,"others":83},{"topic":"Reparations","share":0.0745,"mean":0.004,"rank":2,"others":13},{"topic":"Disaster Risk Reduction","share":0.0676,"mean":0.0015,"rank":2,"others":4},{"topic":"Jamaica","share":0.0668,"mean":0.0,"rank":1,"others":0},{"topic":"Haiti","share":0.062,"mean":0.0062,"rank":11,"others":11},{"topic":"International Law & Order","share":0.0613,"mean":0.0604,"rank":75,"others":102}]};
